// Places one real outbound call through Twilio and plays speech generated by
// ElevenLabs in your chosen voice.
//
//   node scripts/twilio-test-call.js +919876543210
//   node scripts/twilio-test-call.js +919876543210 --text "Hi, this is Synq."
//   node scripts/twilio-test-call.js +919876543210 --audio greeting.mp3
//
// Three steps, each of which fails on its own and says which one it was:
//   1. Make the audio. ElevenLabs turns the text into an mp3; --audio skips this.
//   2. Host it. Twilio can only play audio it can download, so the mp3 goes to
//      a private Supabase bucket behind a link that expires in an hour.
//   3. Call. Twilio rings the number and plays that link.
//
// The destination is a required argument on purpose. A default number here
// would eventually call someone who did not expect it.

const fs = require('fs');
const { readEnvFile, pick } = require('./lib/env');
const { generateSpeech } = require('./generate-speech');

const DEFAULT_TEXT = 'Hello, this is a test call from Synq.';
// On a trial account each verified recipient is tied to one assigned trial
// number, so this has to be configurable rather than assumed.
const DEFAULT_FROM = '+17372508034';

/**
 * Twilio auth failures, as opposed to a refusal of the call itself. A revoked
 * API key reports 8001 on some endpoints and 70051 on the Calls endpoint, so
 * any HTTP 401 is treated as auth too rather than trusting a code list.
 */
const AUTH_ERROR_CODES = new Set([20003, 8001, 70051]);
const isAuthFailure = (status, code) => status === 401 || AUTH_ERROR_CODES.has(code);

function resolveCredentials(env) {
  const accountSid = pick(env, 'TWILIO_ACCOUNT_SID');

  if (!accountSid) {
    throw new Error(
      'TWILIO_ACCOUNT_SID is missing from .env.local. It starts with "AC" and is on the\n' +
        'front page of the Twilio console. An API key cannot replace it, because the\n' +
        'account SID is part of the request URL.'
    );
  }
  if (!accountSid.startsWith('AC')) {
    throw new Error(`TWILIO_ACCOUNT_SID should start with "AC", but starts with "${accountSid.slice(0, 2)}".`);
  }

  // Twilio takes either an API key pair or the account's own auth token. Both
  // are tried in that order, because an API key can be revoked in the console
  // without anything in this file changing.
  const candidates = [];
  const apiKeySid = pick(env, 'TWILIO_API_KEY_SID', 'TWILIO_SALES_CALLIN_API');
  const apiKeySecret = pick(env, 'TWILIO_API_KEY_SECRET', 'TWILIO_CLIENT_SECRET');
  const authToken = pick(env, 'TWILIO_AUTH_TOKEN');

  if (apiKeySid && apiKeySecret) {
    candidates.push({ label: 'API key', user: apiKeySid, pass: apiKeySecret });
  }
  if (authToken) {
    candidates.push({ label: 'auth token', user: accountSid, pass: authToken });
  }

  if (candidates.length === 0) {
    throw new Error(
      'No usable Twilio credentials. Set either TWILIO_AUTH_TOKEN, or an API key pair\n' +
        '(TWILIO_API_KEY_SID and TWILIO_API_KEY_SECRET) in .env.local.'
    );
  }

  return { accountSid, candidates };
}

function parseArgs(argv) {
  const [to, ...rest] = argv;
  const options = { to, text: DEFAULT_TEXT, audioFile: null };
  for (let i = 0; i < rest.length; i++) {
    if (rest[i] === '--text') options.text = rest[++i];
    else if (rest[i] === '--audio') options.audioFile = rest[++i];
    else throw new Error(`Unknown option "${rest[i]}". Use --text "..." or --audio file.mp3.`);
  }
  return options;
}

/** Uploads the mp3 through the call-audio function and returns a signed link. */
async function hostAudio(audio, env) {
  const base = pick(env, 'EXPO_PUBLIC_SUPABASE_URL');
  const anonKey = pick(env, 'EXPO_PUBLIC_SUPABASE_ANON_KEY');
  const token = pick(env, 'SYNQ_CALL_AUDIO_TOKEN');

  if (!base || !anonKey) {
    throw new Error('EXPO_PUBLIC_SUPABASE_URL and EXPO_PUBLIC_SUPABASE_ANON_KEY are needed to host the audio.');
  }
  if (!token) throw new Error('SYNQ_CALL_AUDIO_TOKEN is missing from .env.local.');

  let response;
  try {
    response = await fetch(`${base}/functions/v1/call-audio`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${anonKey}`,
        apikey: anonKey,
        'Content-Type': 'audio/mpeg',
        'x-synq-token': token,
      },
      body: audio,
    });
  } catch (cause) {
    throw new Error(`Could not reach Supabase to host the audio: ${cause.message}`);
  }

  const payload = await response.json().catch(() => ({}));
  if (!response.ok || !payload.url) {
    throw new Error(`Hosting the audio failed (HTTP ${response.status}): ${payload.error || 'no link returned'}`);
  }
  return { url: payload.url, path: payload.path, expiresIn: payload.expires_in };
}

async function placeCall({ to, from, audioUrl, env }) {
  const { accountSid, candidates } = resolveCredentials(env);

  // Twilio's hosted message page. Given a link it answers with <Play>, and
  // unlike inline TwiML it is accepted on trial accounts.
  const instructions =
    'https://twimlets.com/message?' + new URLSearchParams({ 'Message[0]': audioUrl }).toString();
  const body = new URLSearchParams({ To: to, From: from, Url: instructions });
  const url = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Calls.json`;

  let lastError = null;

  for (const credential of candidates) {
    const auth = Buffer.from(`${credential.user}:${credential.pass}`).toString('base64');

    let response;
    try {
      response = await fetch(url, {
        method: 'POST',
        headers: {
          Authorization: `Basic ${auth}`,
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body,
      });
    } catch (cause) {
      throw new Error(`Could not reach Twilio: ${cause.message}`);
    }

    const payload = await response.json().catch(() => ({}));
    if (response.ok) return { ...payload, usedCredential: credential.label };

    // Only a rejected credential is worth retrying with another one. A refused
    // call would be refused identically however we authenticate, and retrying
    // it risks placing the same call twice.
    if (isAuthFailure(response.status, payload.code) && credential !== candidates[candidates.length - 1]) {
      lastError = `${credential.label} rejected (code ${payload.code})`;
      continue;
    }

    const detail = payload.message || `HTTP ${response.status}`;
    const hint =
      payload.code === 21219 || payload.code === 21210
        ? '\nThis is a trial account, so you can only call numbers verified in the Twilio console.'
        : payload.code === 573003
          ? '\nOn a trial, each verified number is tied to one trial number. Set TWILIO_FROM_NUMBER' +
            '\nto the trial number assigned to this recipient.'
          : isAuthFailure(response.status, payload.code)
            ? '\nEvery credential in .env.local was rejected. Check them in the Twilio console.'
            : payload.code === 21212 || payload.code === 21606
              ? `\n${from} is not a number this account can call from.`
              : '';
    const preamble = lastError ? `${lastError}, then ` : '';
    throw new Error(`${preamble}Twilio refused the call (code ${payload.code ?? '?'}): ${detail}${hint}`);
  }

  throw new Error(lastError ?? 'No Twilio credential was accepted.');
}

async function main() {
  const options = parseArgs(process.argv.slice(2));

  if (!options.to) {
    console.error('Usage: node scripts/twilio-test-call.js +<number in E.164> [--text "..." | --audio file.mp3]');
    process.exit(1);
  }
  if (!/^\+\d{8,15}$/.test(options.to)) {
    console.error(`"${options.to}" is not E.164. It needs a leading + and country code, e.g. +919876543210`);
    process.exit(1);
  }

  const env = readEnvFile();
  const from = pick(env, 'TWILIO_FROM_NUMBER') || DEFAULT_FROM;

  let audio;
  if (options.audioFile) {
    console.log(`1/3 Using ${options.audioFile}`);
    audio = fs.readFileSync(options.audioFile);
  } else {
    console.log('1/3 Generating speech with ElevenLabs');
    audio = await generateSpeech(options.text, env);
    console.log(`    ${audio.length} bytes for: "${options.text}"`);
  }

  console.log('2/3 Hosting the audio');
  const hosted = await hostAudio(audio, env);
  console.log(`    stored as ${hosted.path}, link valid for ${Math.round(hosted.expiresIn / 60)} minutes`);

  console.log(`3/3 Calling ${options.to} from ${from}`);
  const call = await placeCall({ to: options.to, from, audioUrl: hosted.url, env });
  console.log(`    authenticated with the ${call.usedCredential}`);
  console.log(`Call SID: ${call.sid}`);
  console.log(`Status:   ${call.status}`);
}

main().catch((error) => {
  console.error(error.message);
  process.exit(1);
});
